      trail += texture2D(uTrail, center + vec2( d.x,  0.0))     * 0.12;
      trail += texture2D(uTrail, center + vec2(-d.x,  0.0))     * 0.12;
      trail += texture2D(uTrail, center + vec2( 0.0,  d.y))     * 0.12;
      trail += texture2D(uTrail, center + vec2( 0.0, -d.y))     * 0.12;
      trail += texture2D(uTrail, center + vec2( d.x,  d.y))     * 0.04;
