    contrib += detectAt(vUv + vec2(       0.0,  uRadiusY));
    contrib += detectAt(vUv + vec2(       0.0, -uRadiusY));
    contrib += detectAt(vUv + vec2( uRadiusX * r,  uRadiusY * r));
    contrib += detectAt(vUv + vec2(-uRadiusX * r,  uRadiusY * r));
